<?php
require_once __DIR__.'/app.php';require_permission('catalog.view');
$id=value_int($_GET['id']??null);if(!$id){http_response_code(404);exit('Không tìm thấy sách.');}
$st=db()->prepare('SELECT b.*,c.name category_name FROM books b LEFT JOIN categories c ON c.id=b.category_id WHERE b.id=?');$st->execute([$id]);$book=$st->fetch();
if(!$book || (!(int)$book['is_active'] && !can('catalog.manage'))){http_response_code(404);exit('Sách không còn hiển thị.');}
$pageTitle='Thông tin sách';require __DIR__.'/partials/header.php'; ?>
<div class="page-head"><div><div class="eyebrow">BOOK DETAILS</div><h1><?= h($book['title']) ?></h1><p>Thông tin đầu sách và tình trạng tồn kho tại cửa hàng.</p></div><a class="btn outline" href="books.php">← Về danh mục</a></div>
<div class="book-detail-layout"><div class="book-art book-art-<?= (int)$book['id']%5 ?> detail-art"><div class="art-lines">✦</div><span class="book-art-label"><?= h($book['category_name']?:'Sách') ?></span><strong><?= h($book['title']) ?></strong><small><?= h($book['author']) ?></small></div><section class="panel"><div class="eyebrow">FEATURED BOOK</div><h1><?= h($book['title']) ?></h1><p class="muted">Tác giả: <?= h($book['author']) ?> · Thể loại: <?= h($book['category_name']?:'Khác') ?></p><div class="price detail-price"><?= money($book['price']) ?></div><p class="muted">Tồn kho: <strong><?= (int)$book['stock'] ?> cuốn</strong></p><p><?= nl2br(h($book['description']?:'Chưa có mô tả cho đầu sách này.')) ?></p><div class="form-actions"><?php if(can('cart.manage')&&(int)$book['is_active']&&(int)$book['stock']>0): ?><form method="post" action="cart.php"><?= csrf_field() ?><input type="hidden" name="action" value="add"><input type="hidden" name="book_id" value="<?= (int)$book['id'] ?>"><input type="hidden" name="quantity" value="1"><button class="btn outline">＋ Thêm giỏ</button></form><?php if(can('orders.place')): ?><form method="post" action="checkout.php"><?= csrf_field() ?><input type="hidden" name="action" value="buy_prepare"><input type="hidden" name="book_id" value="<?= (int)$book['id'] ?>"><button class="btn primary">Mua ngay</button></form><?php endif; ?><?php endif; ?><?php if(can('catalog.manage')): ?><a href="book_form.php?id=<?= (int)$book['id'] ?>" class="btn outline">Chỉnh sửa sách</a><?php endif; ?></div></section></div>
